#!/usr/bin/env python
"""PreToolUse/PostToolUse guard generated by Claude Session Manager (WS-03).

Do not edit by hand: the manager rewrites this file when its rules change and
deletes it when the last rule is taken off (Experience panel -> Waste -> Hook
rules). Every rule below stops a call that earlier runs showed to be wasted
work, and says what to do instead -- a refusal that only said "no" would just
make the model retry.

Escape hatch: a refusal names a marker file. Creating it (empty) lets the next
call through once and is then consumed, so a legitimate repeat is never
blocked for good.

The hook fails open: anything unexpected lets the call through.
"""

import json
import os
import re
import sys
import tempfile

RULES = json.loads(r'''__RULES__''')

_OVERSIZED_CHARS_PER_TOKEN = 4
_EMPTY_RESULT_CHARS = 100
_EMPTY_STREAK = 2
_COMMAND_KEYS = ("command", "cmd", "script")
_EDIT_TOOLS = ("Edit", "Write", "MultiEdit", "NotebookEdit")


def _norm(path):
    return str(path).replace("\\", "/").lower()


def _state_path(session):
    safe = re.sub(r"[^A-Za-z0-9_.-]", "_", str(session or "default"))[:80]
    return os.path.join(tempfile.gettempdir(), "cm-guard-" + safe + ".json")


def _marker_path(session):
    return _state_path(session)[:-5] + ".allow"


def _load(session):
    try:
        with open(_state_path(session), "r", encoding="utf-8") as f:
            st = json.load(f)
            if isinstance(st, dict):
                return st
    except Exception:
        pass
    return {}


def _save(session, st):
    try:
        with open(_state_path(session), "w", encoding="utf-8") as f:
            json.dump(st, f)
    except Exception:
        pass


def _rule(kind):
    for r in RULES:
        if r.get("kind") == kind:
            return r
    return None


def _deny(session, why, instead):
    marker = _marker_path(session)
    sys.stderr.write(
        "BLOCKED by a Claude Session Manager hook rule: " + why + "\n"
        "Instead: " + instead + "\n"
        "If this call really is needed, create an empty file at " + marker +
        " (Write tool, or `touch`) and repeat the call once; the marker is consumed.\n")
    return 2


def _command(tool_input):
    for key in _COMMAND_KEYS:
        v = tool_input.get(key)
        if isinstance(v, str) and v.strip():
            return v
    return ""


def _squash(s):
    return " ".join(s.split())


def _post(payload, session, st):
    tool = payload.get("tool_name")
    if tool not in ("Grep", "Glob"):
        return 0
    resp = payload.get("tool_response")
    text = resp if isinstance(resp, str) else json.dumps(resp, ensure_ascii=False)
    if len(text or "") < _EMPTY_RESULT_CHARS:
        st["empty_streak"] = st.get("empty_streak", 0) + 1
    else:
        st["empty_streak"] = 0
    _save(session, st)
    return 0


def _pre(payload, session, st):
    tool = payload.get("tool_name")
    ti = payload.get("tool_input") or {}

    if tool in _EDIT_TOOLS:
        path = _norm(ti.get("file_path") or ti.get("notebook_path") or "")
        reads = st.setdefault("reads", {})
        for k in [k for k in reads if k.startswith(path + "|")]:
            del reads[k]
        st["edits"] = st.get("edits", 0) + 1
        st["searches"] = {}
        _save(session, st)
        return 0

    marker = _marker_path(session)
    verdict = None
    if tool == "Read":
        path = ti.get("file_path") or ""
        key = _norm(path) + "|" + str(ti.get("offset")) + "|" + str(ti.get("limit"))
        r = _rule("repeat_read")
        reads = st.setdefault("reads", {})
        if r and key in reads:
            verdict = ("this file was already read in this session with no edit to it since, "
                       "so its content is already in your context.",
                       "use what you already have; if only a part is needed, grep -n for it. "
                       "Read it again only if it changed outside your edits.")
        r = _rule("oversized_read")
        if verdict is None and r and ti.get("offset") is None and ti.get("limit") is None:
            try:
                size = os.path.getsize(path)
            except Exception:
                size = 0
            limit = int(r.get("param") or 8000) * _OVERSIZED_CHARS_PER_TOKEN
            if size > limit:
                verdict = ("this file is about %d KB; reading it whole costs tokens on every later step." % (size // 1024),
                           "grep -n for the part you need, then Read it with offset and limit.")
        if verdict is None:
            reads[key] = 1
    elif tool in ("Grep", "Glob"):
        key = tool + "|" + json.dumps(ti, sort_keys=True)
        searches = st.setdefault("searches", {})
        r = _rule("repeat_read")
        if r and key in searches:
            verdict = ("the same %s call was already made and nothing was edited since." % tool,
                       "use the earlier result.")
        r = _rule("empty_search")
        if verdict is None and r and st.get("empty_streak", 0) >= _EMPTY_STREAK:
            st["empty_streak"] = 0
            verdict = ("the last %d searches came back empty - names are being guessed." % _EMPTY_STREAK,
                       "list the directory (ls, or Glob on the parent folder) to see the real names, then search.")
        if verdict is None:
            searches[key] = 1
    elif tool in ("Bash", "PowerShell"):
        cmd = _squash(_command(ti))
        for r in RULES:
            if r.get("kind") == "failure_cmd" and r.get("param") and _squash(r["param"]) in cmd:
                verdict = ("this command is known to fail.",
                           r.get("hint") or "use the form the project notes describe.")
                break

    if verdict is not None and os.path.exists(marker):
        try:
            os.remove(marker)
        except Exception:
            pass
        verdict = None
    _save(session, st)
    if verdict is not None:
        return _deny(session, verdict[0], verdict[1])
    return 0


def main():
    try:
        payload = json.load(sys.stdin)
        session = payload.get("session_id") or "default"
        st = _load(session)
        if payload.get("hook_event_name") == "PostToolUse":
            return _post(payload, session, st)
        return _pre(payload, session, st)
    except Exception:
        return 0


if __name__ == "__main__":
    sys.exit(main())
